INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47011, 'Exodus 39:3', 'Exodus', 39, 3, 'هغوی سره زر وټکول او نرۍ پاڼې یې ورڅخه جوړې کړې او تارونه یې ورڅخه پرې کړل چې په ابي، بانجاني او سرو وړیو او ښه کتان کې ورڅخه کار واخیستل شي، دا د یو ماهر کسبګر کار ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_3.mp3', '', 1761754199, 1761754199),
(47012, 'Exodus 39:4', 'Exodus', 39, 4, 'هغوی د سپېڅلي پېشبند دپاره د اوږې دوه تسمې جوړې کړې او د هغه په دواړو خواو باندې یې ونښلولې چې پېشبند ورسره وتړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_4.mp3', '', 1761754199, 1761754199),
(47013, 'Exodus 39:5', 'Exodus', 39, 5, 'ښه اوبدل شوی کمربند چې د هماغه موادو څخه جوړ شوی ؤ، هغه د سپېڅلي پېشبند سره ونښلول شو چې د یوې ټوټې په شان ښکاره شي. هغوی دا کار د څښتن د حکم سره سم چې موسی ته یې کړی ؤ، وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_5.mp3', '', 1761754199, 1761754199),
(47014, 'Exodus 39:6', 'Exodus', 39, 6, 'هغوی د عقیقو تیږې په هغو ځایونو کې ولګولې چې د سرو زرو د قابونو په شان جوړ شوي دي او په هغو باندې یې د مهر په شان د یعقوب د زامنو د نومونو نقش وویست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_6.mp3', '', 1761754199, 1761754199),
(47015, 'Exodus 39:7', 'Exodus', 39, 7, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، هغوی هغه تیږې د سپېڅلي پېشبند د اوږې په تسمو باندې ولګولې چې د اسراییلو د دولسو قبیلو استازیتوب وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_7.mp3', '', 1761754199, 1761754199),
(47016, 'Exodus 39:8', 'Exodus', 39, 8, 'هغوی سینه پوښ د هماغو موادو څخه جوړ کړ چې سپېڅلی پېشبند ورڅخه جوړ شوی ؤ او هماغسې ګلدوزي شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_8.mp3', '', 1761754199, 1761754199),
(47017, 'Exodus 39:9', 'Exodus', 39, 9, 'هغه څلور کنجه ؤ، دوه ویشت سانتي اوږد او دوه ویشت سانتي پلن ؤ او دوه قاته ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_9.mp3', '', 1761754199, 1761754199),
(47018, 'Exodus 39:10', 'Exodus', 39, 10, 'بیا هغوی په هغه باندې څلور قطاره قیمتي تیږې ولګولې. په لومړي قطار کې یې یو یاقوت، یو زیړ یاقوت او یو لعل ولګاوه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_10.mp3', '', 1761754199, 1761754199),
(47019, 'Exodus 39:11', 'Exodus', 39, 11, 'په دوهم قطار کې یې یو زمرد، یوه د لاجوردو تیږه او یو الماس ولګاوه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_11.mp3', '', 1761754199, 1761754199),
(47020, 'Exodus 39:12', 'Exodus', 39, 12, 'په درېم قطار کې یې یوه فیروزه، یو سپین عقیق او یو بانجاني یاقوت ولګاوه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_12.mp3', '', 1761754199, 1761754199),
(47021, 'Exodus 39:13', 'Exodus', 39, 13, 'په څلورم قطار کې یې یو شینکی یاقوت، د عقیقو یوه تیږه او یو یشم ولګاوه. هغه په داسې ځایونو کې ولګول شول چې د سرو زرو د قابونو په شان جوړ شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_13.mp3', '', 1761754199, 1761754199),
(47022, 'Exodus 39:14', 'Exodus', 39, 14, 'هلته دولس تیږې وې، د یعقوب د زامنو د هر یو نوم دپاره یوه یوه تیږه، په هرې یوې کې د یو مهر په شان نقش ویستل شوی ؤ او د دولسو قبیلو څخه د یوې قبیلې نوم په کې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_14.mp3', '', 1761754199, 1761754199),
(47023, 'Exodus 39:15', 'Exodus', 39, 15, 'هغوی د سینه پوښ دپاره د سوچه سرو زرو څخه داسې زنځیرونه جوړ کړل چې د یوې رسۍ په شان تاو شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_15.mp3', '', 1761754199, 1761754199),
(47024, 'Exodus 39:16', 'Exodus', 39, 16, 'دوه د سرو زرو د قابونو په شان ځایونه او دوه د سرو زرو کړۍ ګانې یې جوړې کړې او د سینه پوښ په پورتنیو کنجونو پورې یې ونښلولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_16.mp3', '', 1761754199, 1761754199),
(47025, 'Exodus 39:17', 'Exodus', 39, 17, 'په دغو دوو کړیو باندې یې دوه د سرو زرو زنځیرونه وتړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_17.mp3', '', 1761754199, 1761754199),
(47026, 'Exodus 39:18', 'Exodus', 39, 18, 'او د زنځیرونو دوه نور سرونه یې په هغو ځایونو باندې چې د سرو زرو د قابونو په شان وو، وتړل او په دې ډول یې د سپېڅلي پېشبند د اوږې د تسمو په مخکینۍ برخې باندې ونښلول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_18.mp3', '', 1761754199, 1761754199),
(47027, 'Exodus 39:19', 'Exodus', 39, 19, 'هغوی د سرو زرو دوه کړۍ ګانې جوړې کړې او د سینه پوښ په لاندېنیو کنجونو پورې یې په دنننۍ څنډې باندې د سپېڅلي پېشبند په څنګ کې ونښلولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_19.mp3', '', 1761754199, 1761754199),
(47028, 'Exodus 39:20', 'Exodus', 39, 20, 'دوه نورې کړۍ ګانې یې جوړې کړې او د اوږې د تسمو په لاندېنۍ برخه کې یې ونښلولې چې د سپېڅلي پېشبند په مخکینۍ برخې باندې بخۍ ته نژدې او د سپېڅلي پېشبند د کمربند دپاسه وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_20.mp3', '', 1761754199, 1761754199),
(47029, 'Exodus 39:21', 'Exodus', 39, 21, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، هغوی د سینه پوښ کړۍ ګانې د سپېڅلي پېشبند د کړۍ ګانو سره په ابي مزي باندې وتړلې چې د کمربند سره وصل شي، ترڅو سینه پوښ د سپېڅلي پېشبند څخه لېرې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_21.mp3', '', 1761754199, 1761754199),
(47030, 'Exodus 39:22', 'Exodus', 39, 22, 'هغه چپنه چې د سپېڅلي پېشبند لاندې اغوستل کېدله ټوله د ابي ټوکر څخه جوړه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_22.mp3', '', 1761754199, 1761754199),
(47031, 'Exodus 39:23', 'Exodus', 39, 23, 'د هغې په منځ کې یې د سر دپاره یو سوری پرېښود او د سوري ګردچاپېره یې یوه غاړه وګنډله، ترڅو چپنه ونه شلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_23.mp3', '', 1761754199, 1761754199),
(47032, 'Exodus 39:24', 'Exodus', 39, 24, 'هغوی د چپنې د لمنې په څنډه باندې د ابي، بانجاني او سرو وړیو او ښه کتان څخه انار جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_24.mp3', '', 1761754199, 1761754199),
(47033, 'Exodus 39:25', 'Exodus', 39, 25, 'د سوچه سرو زرو څخه یې زنګونه جوړ کړل او هغه یې د لمنې په څنډه باندې د انارو ترمنځ ونښلول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_25.mp3', '', 1761754199, 1761754199),
(47034, 'Exodus 39:26', 'Exodus', 39, 26, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، زنګونه او انار د هغې چپنې د لمنې په څنډه باندې چې د خدمت کولو دپاره به اغوستل کېدله، د یو بل ترمنځ راغلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_26.mp3', '', 1761754199, 1761754199),
(47035, 'Exodus 39:27', 'Exodus', 39, 27, 'هغوی د هارون او د هغه د زامنو دپاره د ښه کتان څخه کمیسونه جوړ کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_27.mp3', '', 1761754199, 1761754199),
(47036, 'Exodus 39:28', 'Exodus', 39, 28, 'او لونګۍ، خولۍ ګانې او نېکرونه یې ورته د ښه کتان څخه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_28.mp3', '', 1761754199, 1761754199),
(47037, 'Exodus 39:29', 'Exodus', 39, 29, 'پټۍ د ښه کتان او د ابي، بانجاني او سرو وړیو څخه جوړه شوې وه او هغه ګلدوزي شوې وه، لکه څنګه چې څښتن موسی ته حکم کړی ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_29.mp3', '', 1761754199, 1761754199),
(47038, 'Exodus 39:30', 'Exodus', 39, 30, 'هغوی د سوچه سرو زرو څخه یو ګل جوړ کړ او په هغه باندې یې د دې لغتونو یعنې څښتن ته وقف شوی یو نقش وویست لکه څنګه چې په یو مهر باندې ویستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_30.mp3', '', 1761754199, 1761754199),
(47039, 'Exodus 39:31', 'Exodus', 39, 31, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، هغوی هغه ګل په یو ابي مزي باندې د لونګۍ په مخکینۍ برخې پورې وتاړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_31.mp3', '', 1761754199, 1761754199),
(47040, 'Exodus 39:32', 'Exodus', 39, 32, 'په دې ډول هغه ټول کار چې په سپېڅلې خېمې باندې روان ؤ، هغه ختم شو. اسراییلیانو ټول شیان د څښتن د حکم سره سم چې موسی ته یې کړی ؤ، جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_32.mp3', '', 1761754199, 1761754199),
(47041, 'Exodus 39:33', 'Exodus', 39, 33, 'بیا هغوی دا شیان موسی ته راوړل: خېمه او د هغې ټول سامان، د هغې چنګکونه، چوکاټونه، اړمونه، ستنې او پایې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_33.mp3', '', 1761754199, 1761754199),
(47042, 'Exodus 39:34', 'Exodus', 39, 34, 'د پسه د داسې پوستکي څخه پوښ چې سور رنګ ورکړل شوی ؤ، د ښې څرمنې پوښ او دنننۍ پرده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_34.mp3', '', 1761754199, 1761754199),
(47043, 'Exodus 39:35', 'Exodus', 39, 35, 'د لوظ صندوق چې د تیږو لوحې په کې دي، د هغه د میلو سره او د هغه سرپوښ چې کفاره ورباندې ادا کیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_35.mp3', '', 1761754199, 1761754199),
(47044, 'Exodus 39:36', 'Exodus', 39, 36, 'مېز د هغه د ټول سامان سره او سپېڅلې ډوډۍ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_36.mp3', '', 1761754199, 1761754199),
(47045, 'Exodus 39:37', 'Exodus', 39, 37, 'د سوچه سرو زرو څراغدان، د هغه څراغونه، د هغه ټول سامان او د څراغونو دپاره تېل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_37.mp3', '', 1761754199, 1761754199),
(47046, 'Exodus 39:38', 'Exodus', 39, 38, 'د سرو زرو د قربانۍ ځای، د مسح کولو تېل او خوشبویي، د سپېڅلې خېمې د دروازې دپاره پرده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_38.mp3', '', 1761754199, 1761754199),
(47047, 'Exodus 39:39', 'Exodus', 39, 39, 'د قربانۍ برنجي ځای د هغې د برنجي جالۍ سره، د هغې ستنې او ټول لوښي، تشت د پایې سره،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_39.mp3', '', 1761754199, 1761754199),
(47048, 'Exodus 39:40', 'Exodus', 39, 40, 'د حوېلۍ پردې د هغو د ستنو او پایو سره او د حوېلۍ د دروازې دپاره پرده، د حوېلۍ دپاره رسۍ ګانې او موږي، د سپېڅلې خېمې دپاره ټول سامان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_40.mp3', '', 1761754199, 1761754199),
(47049, 'Exodus 39:41', 'Exodus', 39, 41, 'او ښکلي کالي چې په سپېڅلي ځای کې د خدمت دپاره اغوستل کیږي، د هارون کاهن دپاره ځانګړي کالي او د هغه د زامنو دپاره کالي کله چې هغوی د کاهنانو په توګه خدمت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_41.mp3', '', 1761754199, 1761754199),
(47050, 'Exodus 39:42', 'Exodus', 39, 42, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، اسراییلیانو ټول کارونه سرته رسولي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_42.mp3', '', 1761754199, 1761754199),
(47051, 'Exodus 39:43', 'Exodus', 39, 43, 'موسی ټول کار وکاته او ویې لیدل چې هغوی د څښتن د حکم سره سم کار کړی ؤ. نو هغوی ته یې برکت ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus39_verse_43.mp3', '', 1761754199, 1761754199),
(47052, 'Psalms 30:1', 'Psalms', 30, 1, 'ای څښتنه بیانومه ستا لویي ځکه تا یمه ژغورلی دښمنان دې زما نه دي پریښي چې په ما شي دوی خوشحاله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_1.mp3', '', 1761754199, 1761754199),
(47053, 'Psalms 30:2', 'Psalms', 30, 2, 'ای څښتنه زما خدایه ما فریاد وکړ ستا د کومک دپاره تا شفا راکړله ماته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_2.mp3', '', 1761754199, 1761754199),
(47054, 'Psalms 30:3', 'Psalms', 30, 3, 'زه د مرګ په لار روان وم تا له قبره وساتلم نوی ژوند دې راکړ ماته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_3.mp3', '', 1761754199, 1761754199),
(47055, 'Psalms 30:4', 'Psalms', 30, 4, 'ای څښتن ته وفادارو خلکو! ثنا یې وایئ په سندرو باندې ساتئ یې په یاد شکر یې کړئ چې دا سپېڅلی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_4.mp3', '', 1761754199, 1761754199),
(47056, 'Psalms 30:5', 'Psalms', 30, 5, 'وي غضب د ده یوې شېبې دپاره خو یې فضل وي د ټول عمر دپاره د شپې کېدای شي چې ژړا وي ټوله خو په سهار کې خوشحالي راځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_5.mp3', '', 1761754199, 1761754199),
(47057, 'Psalms 30:6', 'Psalms', 30, 6, 'چې مې احساس د بې‌غمۍ وکړ بیا مې د ځانه سره داسې وویل: «زه به هېڅکله په لړزان نه شم»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_6.mp3', '', 1761754199, 1761754199),
(47058, 'Psalms 30:7', 'Psalms', 30, 7, 'کله چې تا وکړ احسان په ما ای څښتنه زه دې د غره په شان قوي کړمه کله چې مخ دې رانه واړاوه زه ووېرېدم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_7.mp3', '', 1761754199, 1761754199),
(47059, 'Psalms 30:8', 'Psalms', 30, 8, 'ما فریاد وکړ تاته ای څښتنه ما د رحم سوال وکړلو له تا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_8.mp3', '', 1761754199, 1761754199),
(47060, 'Psalms 30:9', 'Psalms', 30, 9, '«زما مرګی به څه فایده ولري؟ څه فایده به وکړي چې قبر ته زه لاړ شم؟ ایا خاورې به ویلی ستا ثنا شي؟ دا به وکړای شي بیان وفا د ستا؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_9.mp3', '', 1761754199, 1761754199),
(47061, 'Psalms 30:10', 'Psalms', 30, 10, 'کړه دعا زما قبوله ای څښتنه رحم وکړه ته په ما ای څښتنه مددګار شه ته زما»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_10.mp3', '', 1761754199, 1761754199),
(47062, 'Psalms 30:11', 'Psalms', 30, 11, 'تا زما ماتم بدل کړ د خوشحالۍ په ګډا تا د ویر جامې زما نه وویستلې دې جامې د خوشحالۍ راواغوستلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_11.mp3', '', 1761754199, 1761754199),
(47063, 'Psalms 30:12', 'Psalms', 30, 12, 'نو زه به غلی پاتې نه شم زه به وایم ستا د ثنا سندره د زړه له تله ای څښتنه! زما خدای یې تل ترتله به زه ستا شکر کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms30_verse_12.mp3', '', 1761754199, 1761754199),
(47064, 'Daniel 4:1', 'Daniel', 4, 1, 'نبوکدنضر بادشاه د دُنيا ټولو خلقو، ټولو قومونو، او ټولو ژبو ويوونکو ته دا پېغام ورولېږلو چې، په خير اوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_1.mp3', '', 1761754199, 1761754199),
(47065, 'Daniel 4:2', 'Daniel', 4, 2, 'زۀ غواړم چې تاسو ته د هغه معجزو او حېرانونکو نښو په حقله خبرې وکړم کومې معجزې چې خُدائ تعالىٰ زما دپاره کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_2.mp3', '', 1761754199, 1761754199),
(47066, 'Daniel 4:3', 'Daniel', 4, 3, 'د هغۀ معجزې څومره لوئ دى، او د هغۀ عجائبات څومره طاقتور دى. د هغۀ بادشاهى تر ابده پورې ده، او د هغۀ بادشاهى نسل در نسل پورې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_3.mp3', '', 1761754199, 1761754199),
(47067, 'Daniel 4:4', 'Daniel', 4, 4, 'ما نبوکدنضر په خپل محل کښې په آرام او عېش عشرت سره ژوند کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_4.mp3', '', 1761754199, 1761754199),
(47068, 'Daniel 4:5', 'Daniel', 4, 5, 'ما يو خوب وليدو کوم چې زۀ ويرولم. کله چې زۀ په خپل کټ کښې پروت وم، نو کومه رويا او تصور چې زما په خيال کښې راغلو نو هغې زۀ ډېر زيات ويرولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_5.mp3', '', 1761754199, 1761754199),
(47069, 'Daniel 4:6', 'Daniel', 4, 6, 'نو ما بيا حکم وکړو چې د بابل ټول هوښيار خلق راوغواړئ چې زما د خوب تعبير وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_6.mp3', '', 1761754199, 1761754199),
(47070, 'Daniel 4:7', 'Daniel', 4, 7, 'نو کله چې جادوګر، فالګر، نجوميان او قسمت معلومونکى راغلل، ما هغوئ ته خوب ووئيلو خو هغوئ د هغې تعبير ما ته ونۀ کړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_7.mp3', '', 1761754199, 1761754199),
(47071, 'Daniel 4:8', 'Daniel', 4, 8, 'خو آخر دانيال زما حضور ته راغلو، او ما ورته خپل خوب بيان کړو. مقدسو معبودانو ورته خاص طاقت ورکړے وو، او ما په هغۀ باندې د خپل معبود بيلطشضر نوم کېښودو. او د معبودانو روح په هغۀ کښې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_8.mp3', '', 1761754199, 1761754199),
(47072, 'Daniel 4:9', 'Daniel', 4, 9, 'ما ورته ووئيل چې، ”بيلطشضر د جادوګرانو مشره زۀ په دې پوهېږم چې د معبودانو روح په تا کښې دے، او هيڅ راز معلومول ستا دپاره مشکل کار نۀ دے. زما خوب داسې دے، او تۀ يې ما ته تعبير راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_9.mp3', '', 1761754199, 1761754199),
(47073, 'Daniel 4:10', 'Daniel', 4, 10, 'کله چې زۀ په خپل کټ کښې اودۀ وم ما دا خوب وليدلو، ما وليدل، زما په وړاندې د زمکې په مينځ کښې يوه ونه ولاړه وه. او هغه ډېره زياته اوچته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_10.mp3', '', 1761754199, 1761754199),
(47074, 'Daniel 4:11', 'Daniel', 4, 11, 'دا ونه ډېره غټه او لوړه او طاقتوره شوه او سر يې د آسمان سره ولګېدو، او دا به د ټولې دُنيا د بل سر نه ښکارېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_11.mp3', '', 1761754199, 1761754199),
(47075, 'Daniel 4:12', 'Daniel', 4, 12, 'د هغې پاڼې ښکلې وې، او مېوه يې ډېره وه، او په دې کښې د هر چا خوراک وو. او د هغې لاندې د مېدان ځناورو د ځان دپاره د پناه ځائ پېدا کړو، او د هوا مارغانو يې په څانګو کښې ځان له جالې جوړې کړې، او هغې نه هر يو مخلوق ته خوراک مِلاوېدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_12.mp3', '', 1761754199, 1761754199),
(47076, 'Daniel 4:13', 'Daniel', 4, 13, 'کله چې ما لا په خوب کښې د دې رويا په حقله سوچ کولو، نو ومې ليدل چې د آسمان نه يوه مقدسه فرښته راکوزېده، چې اخوا ديخوا يې کتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_13.mp3', '', 1761754199, 1761754199),
(47077, 'Daniel 4:14', 'Daniel', 4, 14, 'هغې په زور سره دا اعلان وکړو چې، دا ونه راوغورزوئ او څانګې يې پرې کړئ، د دې پاڼې راوشوکوئ او مېوه يې تس نس کړئ. د دې لاندې ځناور او د څانګو نه يې مارغان وشړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_14.mp3', '', 1761754199, 1761754199),
(47078, 'Daniel 4:15', 'Daniel', 4, 15, 'خو د دې بېخ په زمکه کښې پرېږدئ او د اوسپنې او زېړو پټۍ ترې نه تاو کړئ. او هلته يې په واښو کښې پرېږدئ. نو پرېږدئ چې هغه په پرخه کښې لوند شى او هغه دې په ځنګل کښې د ځناورو سره اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_15.mp3', '', 1761754199, 1761754199),
(47079, 'Daniel 4:16', 'Daniel', 4, 16, 'اووۀ کاله به هغه د انسان عقل نۀ لرى بلکې د هغۀ عقل به د ځناورو وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_16.mp3', '', 1761754199, 1761754199),
(47080, 'Daniel 4:17', 'Daniel', 4, 17, 'د هغه فرښتې د سزا ورکولو فېصله واورولے شوه، ترڅو چې هر يو کس ته د دې پته ولګى چې خُدائ تعالىٰ د انسانانو په بادشاهۍ باندې اختيار لرى او چې هغه چا له وغواړى نو هغۀ له بادشاهى ورکوى، کۀ څۀ هم چې هغه کس ډېر غريب وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_17.mp3', '', 1761754199, 1761754199),
(47081, 'Daniel 4:18', 'Daniel', 4, 18, 'نبوکدنضر بادشاه ووئيل، ”دا هغه خوب دے چې ما وليدلو. نو بيا بيلطشضره، تۀ ما ته د دې تعبير بيان کړه ځکه چې زما يو شاهى مشير هم ما له د دې تعبير نۀ شى راکولے. خو تۀ يې راکولے شې ځکه چې د مقدسو معبودانو روح په تا کښې دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_18.mp3', '', 1761754199, 1761754199),
(47082, 'Daniel 4:19', 'Daniel', 4, 19, 'نو دانيال، چې بل نوم يې بيلطشضر وو، په دې دومره هيبت واخستو چې د څۀ وخت دپاره هيڅ يې هم نۀ شو فرمائيلے، او د هغۀ سوچ هغه وارخطا کړو. نو بادشاه هغۀ ته ووئيل، ”بيلطشضره، په دې خوب او د هغې په مطلب مۀ خفه کېږه.“ خو بيلطشضر ورته په جواب کښې وفرمائيل، ”بادشاه سلامت، زۀ غواړم چې دا خوب او د دې تعبير دې ستا دپاره نه بلکې ستا د دشمنانو دپاره وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_19.mp3', '', 1761754199, 1761754199),
(47083, 'Daniel 4:20', 'Daniel', 4, 20, 'هغه ونه چې تا وليدله، کومه چې دومره لوړه وه چې آسمان ته رسېدلې وه او په دُنيا کښې هر چا ته ښکارېدله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_20.mp3', '', 1761754199, 1761754199),
(47084, 'Daniel 4:21', 'Daniel', 4, 21, 'د هغې پاڼې ښائسته وې او مېوه يې دومره زياته وه چې د ټولې دُنيا دپاره کافى وه. ځنګلى ځناورو د دې لاندې آرام کولو او مارغانو به د دې په څانګو کښې جالې جوړولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_21.mp3', '', 1761754199, 1761754199),
(47085, 'Daniel 4:22', 'Daniel', 4, 22, 'اے بادشاه سلامت، تۀ په خپله هغه ونه يې. تۀ ډېر اوچت او مضبوط شوے يې، تۀ دومره لوئ شوے يې چې لويوالے دې تر آسمانه پورې رسېدلے دے او ستا بادشاهت د زمکې د بله سره پورې رسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_22.mp3', '', 1761754199, 1761754199),
(47086, 'Daniel 4:23', 'Daniel', 4, 23, 'اے بادشاه سلامت، تا يوه مقدسه فرښته وليدله، چې د آسمان نه لاندې راکوزېدله او فرمائيل يې چې، دا ونه ووهئ او تباه يې کړئ، خو د هغې تنه او جرړې په زمکه کښې پرېږدئ او د اوسپنې او زېړو په زنځير يې وتړئ او په واښو کښې يې پرېږدئ. او پرېږده چې په پرخه کښې لوند شى، او چې د اوو کالونو پورې د ځنګلى ځناورو په مينځ کښې پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_23.mp3', '', 1761754199, 1761754199),
(47087, 'Daniel 4:24', 'Daniel', 4, 24, 'اے بادشاه سلامت، ستا د خوب تعبير دا دے کومه فېصله چې خُدائ تعالىٰ ستا خلاف کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_24.mp3', '', 1761754199, 1761754199),
(47088, 'Daniel 4:25', 'Daniel', 4, 25, 'تۀ به د خلقو نه يوې خوا ته وشړلے شې او د ځنګلى ځناورو سره به ژوند کوې، تۀ به لکه د څاروو په شان ګياه خورې او د آسمان په پرخه به تر کولے شې. نو بيا به اووۀ کالونه تير شى ترڅو چې تۀ په دې باندې پوهه شې چې صرف خُدائ تعالىٰ د انسانانو په بادشاهت اختيار لرى او هغه چا له يې ورکوى چې چا له يې زړۀ غواړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_25.mp3', '', 1761754199, 1761754199),
(47089, 'Daniel 4:26', 'Daniel', 4, 26, 'د فرښتې هغه حکم چې د ونې تنه سره د جرړو پرېږدئ نو د هغې مطلب دا دے چې ستا بادشاهى به بيا راشى خو کله چې تاسو آسمانى حکومت ومنئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_26.mp3', '', 1761754199, 1761754199),
(47090, 'Daniel 4:27', 'Daniel', 4, 27, 'بادشاه سلامت، په دې وجه دې زما نصيحت تا ته د منلو وى، د خپلو ګناهونو اعتراف وکړه او هغه په ښو کولو سره پرېږده، او په مظلومانو رحم وکړه او شرارت پرېږده. نو کېدے شى چې په دې کښې به ستا د بادشاهۍ خير قائم پاتې شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_27.mp3', '', 1761754199, 1761754199),
(47091, 'Daniel 4:28', 'Daniel', 4, 28, 'بيا دا هر څۀ په نبوکدنضر بادشاه وشُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_28.mp3', '', 1761754199, 1761754199),
(47092, 'Daniel 4:29', 'Daniel', 4, 29, 'دولس مياشتې وروستو کله چې هغه په بابل کښې د شاهى محل په چت باندې ګرځېدو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_29.mp3', '', 1761754199, 1761754199),
(47093, 'Daniel 4:30', 'Daniel', 4, 30, 'هغۀ ووئيل چې، ”ولې دا هغه لوئ د بابل ښار نۀ دے کوم چې د بادشاهانو د اوسېدو دپاره ما په خپل زور طاقت سره د خپل جلال او شان شوکت د څرګندېدو دپاره آباد کړے دے؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_30.mp3', '', 1761754199, 1761754199),
(47094, 'Daniel 4:31', 'Daniel', 4, 31, 'هغه خبره لا د هغۀ په شونډو وه چې د آسمان نه يو آواز راغلو، ”نبوکدنضر بادشاه ستا دپاره دا حکم دے چې، ستا نه هغه شاهى اختيارات واخستلے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_31.mp3', '', 1761754199, 1761754199),
(47095, 'Daniel 4:32', 'Daniel', 4, 32, 'تۀ به د خلقو نه وشړلے شې او د ځنګلى ځناورو سره به اوسېږې، تۀ به لکه د څاروو په شان ګياه خورې. په دې به اووۀ کالونه تير شې ترڅو چې تۀ په دې باندې پوهه شې چې خُدائ تعالىٰ د انسانانو په بادشاهت اختيار لرى او هغه چا له يې ورکوى چې چا له يې زړۀ غواړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_32.mp3', '', 1761754199, 1761754199),
(47096, 'Daniel 4:33', 'Daniel', 4, 33, 'نو سمدستى هغه څۀ پوره شُو څۀ چې د نبوکدنضر په حقله وئيلى شوى وُو. هغه د خلقو د مينځ نه وشړلے شو او د ځناورو په شان يې ګياه وخوړله. د هغۀ په بدن پرخه ورېدله تر هغې پورې د هغۀ وېښتۀ لکه د شاهين د بڼو په شان لوئ شُو او د هغۀ نوکونه لکه د مارغانو د پنجو په شان اوږدۀ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_33.mp3', '', 1761754199, 1761754199),
(47097, 'Daniel 4:34', 'Daniel', 4, 34, 'د اوو کالونو نه وروستو، ما نبوکدنضر خپلې سترګې د آسمان طرف ته اوچتې کړې، او زما عقل دوباره بحال شو. او ما د خُدائ تعالىٰ ثناء صِفت ادا کړو، او د هغۀ احترام او جلال مې بيان کړو څوک چې د تل دپاره ژوندے دے. د هغۀ بادشاهى تر ابده پورې ده، او د هغۀ بادشاهى نسل در نسل پورې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_34.mp3', '', 1761754199, 1761754199),
(47098, 'Daniel 4:35', 'Daniel', 4, 35, 'د هغۀ په مقابل کښې د زمکې ټول خلق هيڅ نۀ دى. هغه د آسمانى فرښتو او د زمکې د خلقو سره چې څۀ غواړى هغه کوى. د هغۀ لاس هيڅوک نۀ شى نيولے او نۀ ورته څوک دا وئيلے شى چې، ”تا څۀ وکړل؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_35.mp3', '', 1761754199, 1761754199),
(47099, 'Daniel 4:36', 'Daniel', 4, 36, 'په هم هغه وخت کښې کله چې زما عقل کار شروع کړو، نو زما عزت او شان و شوکت ما ته د خپلې بادشاهۍ دپاره واپس مِلاو شو او زما مشيرانو او آفسرانو ما ته حلف راکړو، زۀ په خپل تخت باندې دوباره کښېناستلم. او د پخوا نه زما عزت نور هم زيات شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_36.mp3', '', 1761754199, 1761754199),
(47100, 'Daniel 4:37', 'Daniel', 4, 37, 'نو اوس، زۀ نبوکدنضر، د آسمان د بادشاه ثناء صِفت او لوئى بيانوم، ځکه څۀ چې هغه کوى هغه صحيح دى او د هغۀ ټول کارونه د اِنصاف دى. او هغوئ څوک چې کبر او لوئى کوى نو هغه يې عاجز کولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel4_verse_37.mp3', '', 1761754199, 1761754199),
(47101, 'Jeremiah 30:1', 'Jeremiah', 30, 1, 'د مالِک خُدائ پېغام يرمياه ته ورکړے شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_1.mp3', '', 1761754199, 1761754199),
(47102, 'Jeremiah 30:2', 'Jeremiah', 30, 2, '”دا هغه څۀ دى چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک يې فرمائى چې، ټولې هغه خبرې چې ما تا سره وکړې هغه په يو کِتاب کښې وليکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_2.mp3', '', 1761754199, 1761754199),
(47103, 'Jeremiah 30:3', 'Jeremiah', 30, 3, 'مالِک خُدائ فرمائى چې، ګوره، نو هغه وخت راروان دے چې زۀ به خپل خلق اِسرائيل او يهوداه د جلاوطنۍ نه بحال کړم او هغه مُلک او ځائ ته به يې واپس راولم کوم چې ما د هغوئ پلار نيکۀ له په ميراث کښې ورکړے وو او دا به بيا د هغوئ ملکيت وى، دا مالِک خُدائ فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_3.mp3', '', 1761754199, 1761754199),
(47104, 'Jeremiah 30:4', 'Jeremiah', 30, 4, 'دا هغه خبرې دى چې مالِک خُدائ د اِسرائيل او يهوداه د خلقو په حقله فرمائيلى دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_4.mp3', '', 1761754199, 1761754199),
(47105, 'Jeremiah 30:5', 'Jeremiah', 30, 5, '”مالِک خُدائ فرمائى چې، زۀ د يرې ژړا اورم، هلته دهشت دے او امن نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_5.mp3', '', 1761754199, 1761754199),
(47106, 'Jeremiah 30:6', 'Jeremiah', 30, 6, 'نو زۀ به ستاسو نه دا يو تپوس وکړم چې ولې سړى بچى راوړى څۀ؟ نو دا ولې زۀ چې هر يو تکړه سړى ته ګورم نو لکه د يوې بيمارې ښځې په شان چې د ماشوم د پېدا کېدو وخت يې رانزدې شوے وى هغسې يې لاسونه په خپله ګېډه باندې اېښى وى او هر يو لکه د مړى په شان تک زېړ شوى وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_6.mp3', '', 1761754199, 1761754199),
(47107, 'Jeremiah 30:7', 'Jeremiah', 30, 7, 'افسوس چې هغه ورځ به څومره سخته وى. د هغې ورځې په شان به بله کومه ورځ هم نۀ وى. دا به د يعقوب دپاره سخته ورځ وى، خو په آخر کښې به هغه ترې بچ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_7.mp3', '', 1761754199, 1761754199),
(47108, 'Jeremiah 30:8', 'Jeremiah', 30, 8, 'مالِک خُدائ ربُ الافواج فرمائى چې، په هغه ورځ به د هغوئ د غاړې نه هغه جغ مات کړم او د زنځيرونو نه به يې خلاص کړم او هغوئ به نور د پردو خلقو غلامان نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_8.mp3', '', 1761754199, 1761754199),
(47109, 'Jeremiah 30:9', 'Jeremiah', 30, 9, 'خو هغوئ به د خپل مالِک خُدائ او د داؤد د نسل نه د هغه بادشاه خِدمت وکړى، څوک چې به زۀ په هغوئ باندې مقرروم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_9.mp3', '', 1761754199, 1761754199),
(47110, 'Jeremiah 30:10', 'Jeremiah', 30, 10, 'بلکې مالِک خُدائ فرمائى چې، اے زما خِدمت کوونکيه يعقوبه، مۀ يرېږه. او اے اِسرائيله تۀ مۀ پرېشانه کېږه. زۀ به په يقين سره تا او ستا اولاد په هغه لرې مُلک کښې د جلاوطنۍ نه آزاد کړم. او تۀ به راواپس شې او خير خيريت سره به ژوند کوې. او څوک به تا نۀ شى يرولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_10.mp3', '', 1761754199, 1761754199);